history_memory.text:
// History is a bounded in-memory time-series store of key metrics with
// raw -> 1m -> 5m -> 1h downsampling over 14 days. It is safe for concurrent
// use; Append and Range never perform I/O.
type History struct {
	config       HistoryConfig
	mu           sync.RWMutex
	series       map[string]*series
	dropped      uint64
	dropMinutes  map[int64]bool
	newestMinute int64
}

// NewHistory returns an empty store.
func NewHistory(config HistoryConfig) *History {
	if config.Interval <= 0 {
		config.Interval = DefaultHistoryInterval
	}
	if config.MaxSeries <= 0 {
		config.MaxSeries = DefaultHistorySeries
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = HistoryRetention
	}
	return &History{config: config, series: map[string]*series{}, dropMinutes: map[int64]bool{}}
}

history_append.text:
// Append stores one batch of samples taken at the same time. NaN and
// infinite values are skipped.
func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

history_range.text:
// Range returns matching series' points in [Start, End], oldest first.
func (history *History) Range(query HistoryQuery) HistoryResult {
	if query.End.IsZero() {
		query.End = time.Now()
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	chosen := query.Tier
	if chosen == "" {
		chosen = TierFor(query.Start, time.Now())
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	start, end := query.Start.UnixMilli(), query.End.UnixMilli()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	history.mu.RLock()
	defer history.mu.RUnlock()
	result := HistoryResult{RetentionStart: time.UnixMilli(cutoff).UTC(),
		IntervalSeconds: history.config.Interval.Seconds(), DroppedSeries: history.dropped}
	for minute := range history.dropMinutes {
		if minute >= start/time.Minute.Milliseconds() && minute <= end/time.Minute.Milliseconds() {
			result.Incomplete = true
			break
		}
	}
	keys := slices.Sorted(maps.Keys(history.series))
	for _, key := range keys {
		current := history.series[key]
		if current.metric != query.Metric || !labelsMatch(current.labels, query.Labels) {
			continue
		}
		if query.Rate && !current.counter {
			result.UnsupportedReason = "rate_requires_counter"
			continue
		}
		tierName := chosen
		if query.Tier == "" {
			tierName = current.coveringTier(chosen, start, end, cutoff)
		}
		t, ok := current.tiers[tierName]
		if !ok {
			continue
		}
		out := HistorySeries{Metric: current.metric, Tier: tierName, Labels: labelMap(current.labels)}
		var previous *bucket
		var lastAt int64
		expected := max(history.config.Interval, t.step).Milliseconds()
		for _, b := range t.buckets() {
			if b.lastAt() < cutoff {
				continue
			}
			if b.Start > end {
				break
			}
			if b.Start < start-t.step.Milliseconds() {
				copied := b
				previous = &copied
				continue
			}
			if lastAt != 0 && b.lastAt()-lastAt > 2*expected {
				out.Gaps = true
			}
			lastAt = b.lastAt()
			if query.Rate {
				if previous != nil && b.lastAt() > previous.lastAt() {
					delta := b.Last - previous.Last
					if delta < 0 { // counter reset
						delta = b.Last
					}
					if b.Increased {
						// Growth accumulated per raw sample also counts a
						// reset and recovery inside the bucket.
						delta = b.Increase
					}
					rate := delta / (float64(b.lastAt()-previous.lastAt()) / 1000)
					out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: rate,
						Min: rate, Max: rate})
				}
				copied := b
				previous = &copied
				continue
			}
			value := b.Sum / float64(b.Count)
			if current.counter {
				value = b.Last
			}
			out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: value,
				Min: b.Min, Max: b.Max, Samples: b.Count})
		}
		out.LastObservedAt = time.UnixMilli(lastAt).UTC()
		out.Stale = end-lastAt > 2*expected
		// A stored series without points in the range does not take one
		// of the result's slots.
		if len(out.Points) == 0 {
			continue
		}
		if len(result.Series) == query.MaxSeries {
			result.Truncated = true
			break
		}
		result.Series = append(result.Series, out)
	}
	return result
}

history_export_import.text:
// Export encodes the 1m, 5m and 1h tiers as gzip-compressed JSON of at most
// limit bytes. When everything does not fit it drops the 1m and then the
// 5m tier, and finally keeps only as many hourly series as fit. Raw samples
// are not exported: they cover an hour and are rebuilt quickly after a restart.
func (history *History) Export(limit int) ([]byte, error) {
	history.mu.RLock()
	keys := slices.Sorted(maps.Keys(history.series))
	all := make([]seriesSnapshot, 0, len(keys))
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	for _, key := range keys {
		current := history.series[key]
		if current.last < cutoff {
			continue
		}
		tiers := map[string][]bucket{}
		for _, name := range []string{Tier1m, Tier5m, Tier1h} {
			tiers[name] = slices.DeleteFunc(current.tiers[name].buckets(), func(b bucket) bool {
				return b.lastAt() < cutoff
			})
		}
		all = append(all, seriesSnapshot{Metric: current.metric, Labels: current.labels,
			Counter: current.counter, Last: current.last, Tiers: tiers})
	}
	history.mu.RUnlock()
	encode := func(series []seriesSnapshot) ([]byte, error) {
		var buffer bytes.Buffer
		writer := gzip.NewWriter(&buffer)
		if err := json.NewEncoder(writer).Encode(historySnapshot{Version: historySnapshotVersion,
			SavedAt: time.Now().UTC(), Series: series}); err != nil {
			return nil, err
		}
		if err := writer.Close(); err != nil {
			return nil, err
		}
		return buffer.Bytes(), nil
	}
	data, err := encode(all)
	if err != nil || limit <= 0 || len(data) <= limit {
		return data, err
	}
	for _, name := range []string{Tier1m, Tier5m} {
		for index := range all {
			delete(all[index].Tiers, name)
		}
		data, err = encode(all)
		if err != nil || len(data) <= limit {
			return data, err
		}
	}
	for count := len(all); count > 0; count /= 2 {
		data, err = encode(all[:count])
		if err != nil || len(data) <= limit {
			return data, err
		}
	}
	return encode(nil)
}

// Import merges an exported snapshot into the store. Series already
// present keep their newer data; restored series are bounded by MaxSeries.
func (history *History) Import(data []byte) error {
	reader, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return err
	}
	var snapshot historySnapshot
	if err := json.NewDecoder(io.LimitReader(reader, maxSnapshotInflated)).Decode(&snapshot); err != nil {
		return err
	}
	if snapshot.Version != historySnapshotVersion {
		return errors.New("unsupported history snapshot version")
	}
	history.mu.Lock()
	defer history.mu.Unlock()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	for _, restored := range snapshot.Series {
		labels := sortedLabels(restored.Labels)
		key := seriesKey(restored.Metric, labels)
		if _, exists := history.series[key]; exists || len(history.series) >= history.config.MaxSeries ||
			restored.Metric == "" || restored.Last < cutoff {
			continue
		}
		current := history.newSeries(restored.Metric, labels, restored.Counter)
		current.last = restored.Last
		latest := int64(0)
		for name, buckets := range restored.Tiers {
			t, ok := current.tiers[name]
			if !ok || name == TierRaw {
				continue
			}
			buckets = slices.DeleteFunc(slices.Clone(buckets), func(b bucket) bool {
				return b.Count == 0 || b.lastAt() < cutoff
			})
			for index, b := range buckets {
				if index == len(buckets)-1 {
					// Export includes the bucket being filled: restore it
					// open, so samples resuming in the same step extend it
					// instead of opening a second bucket with that start.
					t.open, t.opened = b, true
					continue
				}
				t.push(b)
			}
			// The newest restored counter value is the baseline of the
			// next sample's increase.
			if len(buckets) > 0 && buckets[len(buckets)-1].lastAt() >= latest {
				latest = buckets[len(buckets)-1].lastAt()
				current.lastValue, current.sampled = buckets[len(buckets)-1].Last, true
			}
		}
		history.series[key] = current
	}
	return nil
}

sampler_nats.text:
if nats := member.NATS; nats != nil {
	gauge(HistNATSConnections, float64(nats.Connections), "member", name)
	gauge(HistNATSRoutes, float64(nats.Routes), "member", name)
	counter(HistNATSInMsgs, float64(nats.InMsgs), "member", name)
	counter(HistNATSOutMsgs, float64(nats.OutMsgs), "member", name)
	counter(HistNATSInBytes, float64(nats.InBytes), "member", name)
	counter(HistNATSOutBytes, float64(nats.OutBytes), "member", name)
	gauge(HistNATSSlow, float64(nats.SlowConsumers), "member", name)
	gauge(HistNATSRouteRTTsTruncated, Bool(nats.RouteRTTsTruncated), "member", name, "server", nats.ServerName)
	for _, route := range nats.RouteRTTs {
		labels := []string{"member", name, "server", nats.ServerName, "peer", route.RemoteName}
		gauge(HistNATSRouteConnections, float64(route.Connections), labels...)
		gauge(HistNATSRouteMeasuredConnections, float64(route.MeasuredConnections), labels...)
		if route.RTTSeconds != nil {
			gauge(HistNATSRouteRTT, *route.RTTSeconds, labels...)
		}
	}
	gauge(HistJSStoreUsed, float64(nats.StoreUsedBytes), "member", name)
	if nats.StoreLimitBytes > 0 {
		gauge(HistJSStoreLimit, float64(nats.StoreLimitBytes), "member", name)
	}
	for _, stream := range nats.Streams {
		// Prefer the leader's own report; any replica's is a
		// fallback. A follower's report also names the leader, so
		// track who reported, not whom the report names.
		own := stream.Leader == nats.ServerName
		if _, ok := streams[stream.Name]; !ok || own && !fromLeader[stream.Name] {
			streams[stream.Name] = stream
			fromLeader[stream.Name] = own
		}
	}
	for _, consumer := range nats.Consumers {
		key := [2]string{consumer.Stream, consumer.Name}
		if existing, ok := consumers[key]; !ok || consumer.NumPending > existing.NumPending {
			consumers[key] = consumer
		}
	}
}

global_view.text:
// View holds the newest rollup of every listed region, in memory.
type View struct {
	mu          sync.Mutex
	local       string
	regions     func() []string
	now         func() time.Time
	rollups     map[string]*Rollup
	persisted   map[string]time.Time // ObservedAt last written to the bucket
	persistedAt map[string]time.Time // wall time of that write
	changed     chan struct{}
}

// NewView follows every region regions() lists; local is always listed.
// now defaults to time.Now.
func NewView(local string, regions func() []string, now func() time.Time) *View {
	if now == nil {
		now = time.Now
	}
	return &View{
		local:       normalize(local),
		regions:     regions,
		now:         now,
		rollups:     map[string]*Rollup{},
		persisted:   map[string]time.Time{},
		persistedAt: map[string]time.Time{},
		changed:     make(chan struct{}),
	}
}

// Regions lists local first, then every other listed region by cell.
func (v *View) Regions() []Region {
	v.mu.Lock()
	defer v.mu.Unlock()
	cells := v.listed()
	out := make([]Region, 0, len(cells))
	for _, cell := range cells {
		out = append(out, v.region(cell))
	}
	return out
}

// Region returns one listed region; false when cell is not listed.
func (v *View) Region(cell string) (Region, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	cell = normalize(cell)
	if !slices.Contains(v.listed(), cell) {
		return Region{}, false
	}
	return v.region(cell), true
}

// Changed returns a channel closed on the next accepted rollup.
func (v *View) Changed() <-chan struct{} {
	v.mu.Lock()
	defer v.mu.Unlock()
	return v.changed
}

// Accept keeps r when it is newer than the held rollup of its cell.
func (v *View) Accept(r Rollup) bool {
	v.mu.Lock()
	defer v.mu.Unlock()
	if validate(r, v.now()) != nil {
		return false
	}
	held := v.rollups[r.Cell]
	if held != nil && !r.ObservedAt.After(held.ObservedAt) {
		return false
	}
	if held == nil && len(v.rollups) >= maxRegions {
		v.prune()
		if len(v.rollups) >= maxRegions {
			return false
		}
	}
	v.rollups[r.Cell] = &r
	close(v.changed)
	v.changed = make(chan struct{})
	return true
}

resource_history.text:
// CollectResources reads authenticated whole-node reports by their host origin.
// Controller member names never select a node's physical resources.
func CollectResources(node Node, history observability.HistorySource, now time.Time) *ResourceView {
	resources := new(ResourceView)
	received := resources.latest(history, observability.HistHostReceivedAt, node.Name, now)
	if received == nil || received.Value <= 0 || received.Value > float64(now.UnixMilli()) {
		return resources
	}
	resources.batchAt = received.ObservedAt
	resources.ObservedAt = time.UnixMilli(int64(received.Value)).UTC()
	if incomplete := resources.latest(history, observability.HistHostFSIncomplete, node.Name, now); incomplete != nil && incomplete.Value == 1 {
		resources.Incomplete = true
	}
	resources.CPUCores = resources.latest(history, observability.HistHostCPUCores, node.Name, now)
	resources.CPU = resources.latest(history, observability.HistHostCPUUtilization, node.Name, now)
	resources.MemoryBytes = resources.latest(history, observability.HistHostMemoryTotal, node.Name, now)
	resources.Memory = resources.latest(history, observability.HistHostMemoryRatio, node.Name, now)
	resources.Disk = resources.latest(history, observability.HistHostDiskRatio, node.Name, now)
	if resources.MemoryBytes != nil && resources.Memory != nil && resources.MemoryBytes.ObservedAt.Equal(resources.Memory.ObservedAt) {
		resources.MemoryUsedBytes = &Reading{Value: resources.MemoryBytes.Value * resources.Memory.Value, ObservedAt: resources.Memory.ObservedAt}
	}
	resources.filesystems(history, node.Name, now)
	return resources
}

func (resources *ResourceView) latest(history observability.HistorySource, metric, member string, now time.Time) *Reading {
	result := resources.query(history, metric, member, now)
	var reading *Reading
	for _, series := range result.Series {
		if latest := latestReading(series.Points, now); latest != nil && (reading == nil || latest.ObservedAt.After(reading.ObservedAt)) {
			reading = latest
		}
	}
	if reading != nil && reading.Value == 0 && (metric == observability.HistHostCPUCores || metric == observability.HistHostMemoryTotal) {
		return nil
	}
	if reading != nil && metric != observability.HistHostReceivedAt {
		if !reading.ObservedAt.Equal(resources.batchAt) {
			return nil
		}
		reading.ObservedAt = resources.ObservedAt
	}
	return reading
}

func (resources *ResourceView) query(history observability.HistorySource, metric, member string, now time.Time) observability.HistoryResult {
	if history == nil {
		return observability.HistoryResult{}
	}
	result := history.Range(observability.HistoryQuery{Metric: metric, Labels: map[string]string{"member": strings.ToLower(member)},
		Start: now.Add(-time.Hour), End: now, Tier: observability.TierRaw})
	resources.Pending = resources.Pending || result.Pending
	resources.Incomplete = resources.Incomplete || result.Incomplete || result.Truncated
	return result
}

func latestReading(points []observability.Point, now time.Time) *Reading {
	var reading *Reading
	for _, point := range points {
		if math.IsNaN(point.Value) || math.IsInf(point.Value, 0) || point.Value < 0 || point.Time.After(now) {
			continue
		}
		if reading == nil || point.Time.After(reading.ObservedAt) {
			reading = &Reading{Value: point.Value, ObservedAt: point.Time}
		}
	}
	return reading
}

resource_filesystems.text:
func (resources *ResourceView) filesystems(history observability.HistorySource, member string, now time.Time) {
	type identity struct {
		role, path, device string
	}
	entries := map[identity]*Filesystem{}
	for _, metric := range []string{observability.HistHostFSSize, observability.HistHostFSUsed, observability.HistHostFSRatio,
		observability.HistHostFSFiles, observability.HistHostFSFilesFree} {
		for _, series := range resources.query(history, metric, member, now).Series {
			reading := latestReading(series.Points, now)
			if reading == nil || !reading.ObservedAt.Equal(resources.batchAt) {
				continue
			}
			reading.ObservedAt = resources.ObservedAt
			key := identity{role: series.Labels["role"], path: series.Labels["path"], device: series.Labels["device"]}
			entry := entries[key]
			if entry == nil {
				entry = &Filesystem{Role: key.role, Path: key.path, Device: key.device}
				entries[key] = entry
			}
			switch metric {
			case observability.HistHostFSSize:
				if reading.Value > 0 {
					entry.SizeBytes = reading
				}
			case observability.HistHostFSUsed:
				entry.UsedBytes = reading
			case observability.HistHostFSRatio:
				entry.UsedRatio = reading
			case observability.HistHostFSFiles:
				entry.Files = reading
			case observability.HistHostFSFilesFree:
				entry.FilesFree = reading
			}
		}
	}
	devices := map[string]int{}
	for _, key := range slices.SortedFunc(maps.Keys(entries), func(left, right identity) int {
		return cmp.Or(cmp.Compare(left.role, right.role), cmp.Compare(left.path, right.path), cmp.Compare(left.device, right.device))
	}) {
		entry := entries[key]
		if entry.Device != "" && entry.Device != "0" {
			if index, found := devices[entry.Device]; found {
				resources.Filesystems[index].Role += ", " + entry.Role
				continue
			}
			devices[entry.Device] = len(resources.Filesystems)
		}
		resources.Filesystems = append(resources.Filesystems, *entry)
	}
}

topology_region.text:
func (current view) topologyRegion(summary regionview.Summary, x, top int, nats bool, edges *[]topoEdge) topoRegion {
	local := summary.Local
	region := topoRegion{topoBox: topoBox{X: x, Y: top, W: 2*topoPad + topoReplLane + topoNodeW}, Name: upper(summary.Region),
		Href: current.State.link("/region", "r", summary.Region)}
	if nats {
		region.W += topoNATSLane
	}
	region.Status, region.Caption = regionStatus(summary.Health.Status), string(summary.Health.Status)
	if summary.Health.Status == "" {
		region.Status, region.Caption = boolStatus(current.Ready), "this region"
	}
	if city := regionName(summary.Region); city != "" {
		region.Caption = city + " · " + region.Caption
	}
	members := map[string]regionview.Member{}
	for _, member := range summary.Members {
		members[member.Name] = member
	}
	seats := map[string]regionview.Host{}
	for _, host := range summary.Hosts {
		seats[host.Name] = host
	}
	snapshots := map[string]*observability.MemberSnapshot{}
	if local {
		all := current.members()
		for index := range all {
			snapshots[all[index].Member] = &all[index]
		}
	}
	peers := map[string]observability.PeerView{}
	if local {
		peers = current.metaPeers()
	}
	nodeX := x + topoPad + topoReplLane
	y := top + topoHeader
	for _, node := range topologyNodes(summary) {
		box := current.topologyNode(summary, node, members, seats, local, peers)
		box.X, box.Y, box.W = nodeX, y, topoNodeW
		box.H = topoNodeHead + len(box.Rows)*topoRowH + 6
		for index := range box.Rows {
			box.Rows[index].X, box.Rows[index].Y = nodeX+12, y+topoNodeHead+index*topoRowH+10
			box.Rows[index].DX, box.Rows[index].Width = 132, topoNodeW-12-132-8
		}
		region.Nodes = append(region.Nodes, box)
		y += box.H + topoNodeGap
	}
	if local {
		*edges = append(*edges, current.replicationEdges(region.Nodes)...)
	}
	if nats {
		y = max(y, current.natsLane(&region, summary, members, snapshots, peers, local, edges))
	}
	region.H = max(y-top, topoHeader+20) + topoPad - topoNodeGap
	return region
}
